      "soru": "1982 Anayasası'na göre temel hak ve hürriyetlerin sınırlanması ile ilgili aşağıdakilerden hangisi doğru değildir?",
      "secenekler": ["Temel hak ve hürriyetler, özlerine dokunulmaksızın yalnızca Anayasanın ilgili maddelerinde belirtilen sebeplere bağlı olarak sınırlanabilir.", "Anayasanın sözüne ve ruhuna aykırı olamaz.", "Demokratik toplum düzenine aykırı olamaz.", "Lâik Cumhuriyetin gereklerine ve ölçülülük ilkesine aykırı olamaz.", "Temel hak ve hürriyetler ancak anayasayla sınırlanabilir."],
