      "unite": 5,
      "zorluk": "kolay",
      "soru": "1982 Anayasası'nda yer verilen dernek kurma hürriyeti ile ilgili aşağıdaki ifadelerden hangisi doğru değildir?",
      "secenekler": ["Herkes, önceden izin almaksızın dernek kurma ve bunlara üye olma hürriyetine sahiptir.", "Hiç kimse bir derneğe üye olmaya ve dernekte üye kalmaya zorlanamaz.", "Dernek kurma hürriyeti ancak, millî güvenlik, kamu düzeni, suç işlenmesinin önlenmesi, genel sağlık ve genel ahlâk ile başkalarının hürriyetlerinin korunması sebepleriyle ve kanunla sınırlanabilir.", "Dernekler, kanunun öngördüğü hallerde gecikmesinde sakınca bulunan hallerde savcının yazılı talimatıyla kapatılabilir.", "Dernekler, kanunun öngördüğü hallerde hâkim kararıyla faaliyetten alıkonulabilir."],
      "cevap": "D",
      "kaynak": "Kitap · Kitap Testi 2 · S13",
