      "soru": "1982 Anayasası'nda yer alan siyasi partilere ilişkin hükümlerle ilgili aşağıdaki ifadelerden hangisi yanlıştır?",
      "secenekler": ["Vatandaşlar, siyasî parti kurma ve usulüne göre partilere girme, ayrılma hakkına sahiptir.", "Parti üyesi olabilmek için on sekiz yaşını doldurmuş olmak gerekir.", "Siyasî partiler, demokratik siyasî hayatın vazgeçilmez unsurlarıdır.", "Siyasî partiler YSK'dan izin alarak kurulurlar. Kanun çerçevesinde faaliyet gösterirler.", "Siyasî partilerin tüzük ve programları ile eylemleri, suç işlenmesini teşvik edemez."],
