      "zorluk": "kolay",
      "soru": "1982 Anayasası'na göre aşağıdakilerden hangisi siyasi partiler ile ilgili yanlış bir ifadedir?",
      "secenekler": ["Siyasî partiler, ticarî faaliyetlere girişemezler.", "Siyasî partilerin gelir ve giderlerinin amaçlarına uygun olması gereklidir.", "Yüksek Seçim Kurulunca siyasî partilerin mal edinimleri ile gelir ve giderlerinin kanuna uygunluğunun tespiti yapılır.", "Siyasî partilerin kapatılması, Yargıtay Cumhuriyet Başsavcısının açacağı dava üzerine Anayasa Mahkemesince kesin olarak karara bağlanır.", "Bir siyasî partinin tüzüğü ve programının 68 inci maddenin dördüncü fıkrası hükümlerine aykırı bulunması halinde temelli kapatma kararı verilir."],
