      "secenekler": ["Hâkimler ve savcılar", "Yüksek yargı organları mensupları", "İşçi niteliği taşımayan diğer kamu görevlileri", "Kamu kuruluşlarının işçi statüsündeki görevlileri", "Yükseköğretim Kurulu üyeleri"],
