      "soru": "TBMM üyeleri, Meclis çalışmalarındaki oy ve sözlerinden, Mecliste ileri sürdükleri düşüncelerden, o oturumdaki Başkanlık Divanının teklifi üzerine Meclisçe başka bir karar alınmadıkça bunları Meclis dışında tekrarlamak ve açığa vurmaktan sorumlu tutulamazlar.\nYukarıda aşağıdakilerden hangisinin tanımı yapılmıştır?",
      "secenekler": ["Yasama sorumsuzluğu", "Yasama dokunulmazlığı", "Kadük", "Yasama kısıntısı", "Yargı kısıntısı"],
