      "soru": "1982 Anayasası'nda yer alan suç ve cezalara ilişkin bilgilerden hangisi yanlıştır?",
      "secenekler": ["Kimse, işlendiği zaman yürürlükte bulunan kanunun suç saymadığı bir fiilden dolayı cezalandırılamaz.", "Ceza ve ceza yerine geçen güvenlik tedbirleri ancak kanun ve kanun hükmünde kararname ile konulabilir.", "Suçluluğu hükmen sabit oluncaya kadar, kimse suçlu sayılamaz.", "Hiç kimse kendisini ve kanunda gösterilen yakınlarını suçlayan bir beyanda bulunmaya zorlanamaz.", "Kanuna aykırı olarak elde edilmiş bulgular, delil olarak kabul edilemez."],
