      "soru": "I - Ekonomik, ticari veya teknik ilişkileri düzenleyen\nII - Süresi bir yılı aşmayan\nIII - Devlet maliyesi bakımından bir yüklenme getirmeyen\nIV - Cumhurbaşkanı'nın takdir yetkisi\nYukarıdakilerden hangilerinin bulunması durumunda milletlerarası antlaşmalar yayımlanma ile yürürlüğe girer?",
