      "unite": 6,
      "zorluk": "zor",
      "soru": "1982 Anayasası göz önüne alındığında aşağıdaki ifadelerden hangisi yanlıştır?",
      "secenekler": ["Anayasanın değiştirilmesi Türkiye Büyük Millet Meclisi üye tamsayısının en az dörtte biri tarafından yazıyla teklif edilebilir.", "Anayasanın değiştirilmesi hakkındaki teklifler Genel Kurulda iki defa görüşülür.", "Değiştirme teklifinin kabulü Meclisin üye tamsayısının beşte üç çoğunluğunun gizli oyuyla mümkündür.", "Anayasanın değiştirilmesi hakkındaki tekliflerin görüşülmesi ve kabulü, bu maddedeki kayıtlar dışında, kanunların görüşülmesi ve kabulü hakkındaki hükümlere tâbidir.", "Cumhurbaşkanı Anayasa değişikliklerine ilişkin kanunları, bir daha görüşülmek üzere Türkiye Büyük Millet Meclisine geri gönderebilir."],
