      "soru": "Anayasanın aşağıdaki hükümlerinden hangisi yanlış verilmiştir?",
      "secenekler": ["Egemenliğin kullanılması, hiçbir surette hiçbir kişiye, zümreye veya sınıfa bırakılamaz.", "Hiçbir kimse veya organ kaynağını Anayasadan almayan bir Devlet yetkisi kullanamaz.", "Türk Milleti, egemenliğini, Anayasanın koyduğu esaslara göre, yetkili organları eliyle kullanır.", "Yargı yetkisi, Türk Milleti adına bağımsız mahkemelerce kullanılır.", "Yasama yetkisi Türk Milleti adına TBMM'nindir. Bu yetki devredilemez."],
