      "soru": "Anayasada yer alan hak ve hürriyetlerden hiçbiri, Devletin ülkesi ve milletiyle bölünmez bütünlüğünü bozmayı ve insan haklarına dayanan demokratik ve lâik Cumhuriyeti ortadan kaldırmayı amaçlayan faaliyetler biçiminde kullanılamaz.\nHüküm aşağıdakilerden hangisinin açıklamasıdır?",
      "secenekler": ["Temel hak ve hürriyetlerin niteliği", "Temel hak ve hürriyetlerin sınırlanması", "Temel hak ve hürriyetlerin kötüye kullanılamaması", "Temel hak ve hürriyetlerin kullanılmasının durdurulması", "Kişi hürriyeti ve güvenliği"],
