      "soru": "Devlet, herkesin hayatını, beden ve ruh sağlığı içinde sürdürmesini sağlamak; insan ve madde gücünde tasarruf ve verimi artırarak, işbirliğini gerçekleştirmek amacıyla sağlık kuruluşlarını tek elden planlayıp hizmet vermesini düzenler.\nAnayasa, yukarıdaki hükmüyle aşağıdakilerden hangisini korumayı amaçlar?",
