      "secenekler": ["Herkes, önceden izin almaksızın dernek kurma ve bunlara üye olma ya da üyelikten çıkma hürriyetine sahiptir.", "Hiç kimse bir derneğe üye olmaya ve dernekte üye kalmaya zorlanamaz.", "Dernek kurma hürriyeti ancak, millî güvenlik, kamu düzeni, suç işlenmesinin önlenmesi, genel sağlık ve genel ahlâk ile başkalarının hürriyetlerinin korunması sebepleriyle ve kanunla sınırlanabilir.", "Dernekler, kanunun öngördüğü hallerde mahkeme kararıyla kapatılabilir.", "Dernek kurma hürriyetinin kullanılmasında uygulanacak şekil, şart ve usuller kanunda gösterilir."],
