      "soru": "Siyasi partilerin uyacakları esaslarla ilgili hangisi yanlış hükümdür?",
      "secenekler": ["Siyasi partilerin faaliyetleri, parti içi düzenlemeleri ve çalışmaları demokrasi ilkelerine uygun olur.", "Temelli kapatılan bir parti bir başka ad altında kurulabilir.", "Siyasi partiler, ticari faaliyetlere girişemezler.", "Siyasi partilerin gelir ve giderlerinin amaçlarına uygun olması gereklidir.", "Bu kuralın uygulanması kanunla düzenlenir."],
