      "secenekler": ["TBMM adına Türk Silahlı Kuvvetleri'nin Başkomutanlığını temsil eder.", "Anayasa değişikliklerine ilişkin kanunları gerekli gördüğü takdirde halkoyuna sunar.", "Milli güvenlik politikalarını belirler ve gerekli tedbirleri alır.", "Milletlerarası antlaşmaları onaya sunar.", "Türk Silahlı Kuvvetleri'nin kullanılmasına karar verir."],
