      "zorluk": "orta",
      "soru": "Anayasa Mahkemesinin çalışma ve yargılama usulüyle ilgili aşağıdakilerden hangisi yanlış verilmiştir?",
      "secenekler": ["Anayasa Mahkemesi iki bölüm ve Genel Kurul halinde çalışır.", "Bölümler, başkanvekili başkanlığında dört üyenin katılımıyla toplanır.", "Genel Kurul, Mahkeme Başkanının veya Başkanın belirleyeceği başkanvekilinin başkanlığında en az on üç üye ile toplanır.", "Bölümler ve Genel Kurul kararlarını salt çoğunlukla alır.", "Anayasa Mahkemesi Yüce Divan sıfatıyla baktığı davalar dışında kalan işleri dosya üzerinde inceler."],
