      "zorluk": "orta",
      "soru": "HSK üye seçimlerine ilişkin aşağıdakilerden hangisinde yanlışlık mevcuttur?",
      "secenekler": ["Üç üyesi birinci sınıf olup, birinci sınıfa ayrılmayı gerektiren nitelikleri yitirmemiş adlî yargı hâkim ve savcıları arasından", "Bir üyesi birinci sınıf olup, birinci sınıfa ayrılmayı gerektiren nitelikleri yitirmemiş idarî yargı hâkim ve savcıları arasından", "Üç üyesi Yargıtay üyeleri arasından", "Üç üyesi Danıştay üyeleri arasından", "Üç üyesi nitelikleri kanunda belirtilen yükseköğretim kurumlarının hukuk dallarında görev yapan öğretim üyeleri ile avukatlar arasından"],
