      "unite": 9,
      "zorluk": "orta",
      "soru": "HSK'ya ilişkin aşağıdaki bilgilerden hangisi yanlıştır?",
      "secenekler": ["Hâkimler ve Savcılar Kurulu, mahkemelerin bağımsızlığı ve hâkimlik teminatı esaslarına göre kurulur ve görev yapar.", "Üyeler dört yıl için seçilir.", "Süresi biten üyeler bir daha seçilemez.", "Kurulun meslekten çıkarma cezasına ilişkin olanlar dışındaki kararlarına karşı yargı mercilerine başvurulamaz.", "Kurul Başkanı dairelerin çalışmalarına katılamaz."],
