      "soru": "TBMM İçtüzük, siyasi parti grupları ve kolluk işleri ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?",
      "secenekler": ["Türkiye Büyük Millet Meclisi, çalışmalarını, kendi yaptığı İçtüzük hükümlerine göre yürütür.", "İçtüzük hükümleri, siyasi parti gruplarının, Meclisin bütün faaliyetlerine üye sayısı oranında katılmalarını sağlayacak yolda düzenlenir.", "Siyasi parti grupları, en az 30 üyeden meydana gelir.", "Türkiye Büyük Millet Meclisi'nin bütün bina, tesis, eklenti ve arazisinde kolluk ve yönetim hizmetleri Meclis Başkanlığı eliyle düzenlenir ve yürütülür.", "Emniyet ve diğer kolluk hizmetleri için yeteri kadar kuvvet ilgili makamlarca Meclis Başkanlığı'na tahsis edilir."],
      "cevap": "C",
      "aciklama": "Siyasi parti grupları en az 20 üyeden oluşur (m.95).",
