      "soru": "Aşağıdakilerden hangisi 1982 Anayasası'nda düzenlenen vergi ödevi ile ilgili doğru bir ifade değildir?",
      "secenekler": ["Herkes, kamu giderlerini karşılamak üzere, mali gücüne göre, vergi ödemekle yükümlüdür.", "Vergi yükünün adaletli ve dengeli dağılımı, maliye politikasının sosyal aracıdır.", "Vergi, resim, harç ve benzeri mali yükümlülükler kanunla konulur, değiştirilir veya kaldırılır.", "Vergi, resim, harç ve benzeri mali yükümlülüklerin muaflık, istisnalar ve indirimleriyle oranlarına ilişkin hükümlerinde kanunun belirttiği yukarı ve aşağı sınırlar içinde değişiklik yapmak yetkisi Cumhurbaşkanına verilebilir.", "Vergi yükünün adaletli bir şekilde dağıtılması gerekir."],
